    <button disabled={saving} className="rounded-lg bg-blue-700 px-4 py-2 text-white hover:bg-blue-800 focus-visible:outline-2 focus-visible:outline-offset-2 disabled:opacity-50">
      {saving ? "Saving…" : children}
    </button>
  );
}
